// ContentPost.js
import React from "react";

export default function ContentPost({ title, description, image }) {
  return (
    <section>
        <div className="container px-5 py-10 mx-auto text-center lg:px-40">
            <div className="flex relative z-10 w-full border-4 border-gray-800 bg-gray-900 hover:bg-gray-800 transition-colors duration-300">
                <div className="mb-8">
                {image && (
                    <img
                    className="w-full mb-4 rounded-lg shadow-lg"
                    src={image}
                    alt={title}
                    />
                )}
                {title && (
                    <h2 className="text-3xl font-semibold text-white mb-2">{title}</h2>
                )}
                {description && (
                    <p className="text-lg text-blue-200 leading-relaxed">{description}</p>
                )}
                </div>
            </div>
        </div>


    </section>

  );
}
